glute_bridge:{setup:'Nằm ngửa, gối co, bàn chân gần mông và rộng bằng hông.',steps:['Siết bụng nhẹ.','Đẩy gót nâng hông tới khi vai–hông–gối gần thẳng.','Siết mông rồi hạ chậm.'],cues:['Xương sườn không bật lên','Ép mông ở đỉnh'],mistakes:['Ưỡn lưng thay vì duỗi hông','Đẩy bằng mũi chân'],breathing:'Thở khi nâng hông, hít khi hạ.'},
db_rdl:{setup:'Đứng cầm tạ trước đùi, chân rộng bằng hông, gối hơi cong.',steps:['Đẩy hông ra sau, tạ trượt sát chân.','Hạ tới khi gân kheo căng mà lưng vẫn trung lập.','Siết mông đẩy hông về trước để đứng.'],cues:['Đây là hinge, không phải squat','Tạ luôn gần chân'],mistakes:['Cong lưng','Gập gối quá nhiều'],breathing:'Hít khi hạ, thở khi đứng.'},
calf_raise:{setup:'Đứng thẳng, có thể bám nhẹ vào tường/ghế để cân bằng.',steps:['Nâng gót lên cao bằng đầu bàn chân.','Giữ 1 nhịp ở đỉnh.','Hạ gót chậm xuống.'],cues:['Không nhún lấy đà','Giữ cổ chân thẳng'],mistakes:['Rep quá nhanh','Lật cổ chân ra ngoài'],breathing:'Thở khi nâng, hít khi hạ.'},
