hollow:{setup:'Nằm ngửa, ép lưng dưới sát sàn.',steps:['Nâng vai khỏi sàn.','Duỗi chân và tay xa dần nhưng vẫn giữ lưng dưới áp sàn.','Giữ tư thế trong thời gian mục tiêu.'],cues:['Lưng dưới không được bật khỏi sàn','Thu chân lại nếu quá khó'],mistakes:['Ưỡn lưng','Căng cổ'],breathing:'Thở ngắn, đều; không nín thở.'},
leg_raise:{setup:'Nằm ngửa, chân duỗi; tay có thể đặt dưới mông nếu cần.',steps:['Ép lưng dưới xuống sàn.','Nâng hai chân lên có kiểm soát.','Hạ tới trước khi lưng dưới bắt đầu cong.'],cues:['Dùng bụng giữ xương chậu','Hạ chậm'],mistakes:['Vung chân','Hạ quá thấp làm lưng ưỡn'],breathing:'Thở ra khi nâng, hít khi hạ.'},
hanging_knee:{setup:'Treo xà ổn định với vai active nhẹ.',steps:['Siết core, kéo gối về ngực.','Giữ một nhịp ở trên.','Hạ chân chậm, hạn chế đung đưa.'],cues:['Cuộn xương chậu lên','Không lấy đà'],mistakes:['Đung đưa mạnh','Chỉ gập hông mà không siết bụng'],breathing:'Thở khi nâng gối, hít khi hạ.'},
